def gap_features(Ii,Oo,name):
    n=len(Ii); m=len(Ii[0])
    c=Counter(x for r in Ii for x in r); bg=c.most_common(1)[0][0]
    Lc=[k for k in c if k!=bg][0]
    M={(i,j) for i in range(n) for j in range(m) if Ii[i][j]==Lc}
    rows=[i for i in range(n) if any(Ii[i][j]==Lc for j in range(m))]
    cols=[j for j in range(m) if any(Ii[i][j]==Lc for i in range(n))]
    out=[]
    def perp_dist(i,j,axis):
        # nearest mark strictly perpendicular (same row for col-gap endpoint: marks in same COLUMN above/below)
        if axis=='col-gap':  # endpoint of vertical gap: look left/right in row i
            ds=[abs(j-jj) for jj in range(m) if (i,jj) in M and jj!=j]
        else:
            ds=[abs(i-ii) for ii in range(n) if (ii,j) in M and ii!=i]
        return min(ds) if ds else 99
    def n_between_row(i,a,b):
        # marks strictly inside columns a..b other than endpoints' column? count marks in rows a+1..b-1 between cols? simpler: marks in same column range rows between
        return 0
    for i in range(n):
        js=sorted(j for j in range(m) if (i,j) in M)
        for a,b in zip(js,js[1:]):
            if b-a>1:
                filled=all(Oo[i][j]==2 for j in range(a+1,b))
                f=dict(kind='row',len=b-a-1,pd_a=perp_dist(i,a,'row-gap'),pd_b=perp_dist(i,b,'row-gap'),
                       nrow=len(js), filled=filled)
                out.append((name,f))
    for j in range(m):
        isv=sorted(i for i in range(n) if (i,j) in M)
        for a,b in zip(isv,isv[1:]):
            if b-a>1:
                filled=all(Oo[i][j]==2 for i in range(a+1,b))
                f=dict(kind='col',len=b-a-1,pd_a=perp_dist(a,j,'col-gap'),pd_b=perp_dist(b,j,'col-gap'),
                       ncol=len(isv), filled=filled)
                out.append((name,f))
    return out
