def perp(Ii,M,i,j,axis):
    n=len(Ii); m=len(Ii[0])
    if axis=='row':  # marks in same column
        ds=[abs(i-ii) for ii in range(n) if (ii,j) in M and ii!=i]
    else:            # marks in same row
        ds=[abs(j-jj) for jj in range(m) if (i,jj) in M and jj!=j]
    return min(ds) if ds else 99
def transformR1(grid, lc=1.0, la='dr', lc2=None):
    # lc: L clearance threshold multiplier; straight: pd>=len
    g=[list(r) for r in grid]; n=len(g); m=len(g[0])
    c=Counter(x for r in grid for x in r); bg=c.most_common(1)[0][0]
    Lc=[k for k in c if k!=bg][0]
    M={(i,j) for i in range(n) for j in range(m) if grid[i][j]==Lc}
    for i in range(n):
        js=sorted(j for j in range(m) if (i,j) in M)
        for a,b in zip(js,js[1:]):
            ln=b-a-1
            if ln<1: continue
            if max(perp(grid,M,i,a,'col'), perp(grid,M,i,b,'col')) >= ln:
                for j in range(a+1,b):
                    if g[i][j]==bg: g[i][j]=2
    for j in range(m):
        isv=sorted(i for i in range(n) if (i,j) in M)
        for a,b in zip(isv,isv[1:]):
            ln=b-a-1
            if ln<1: continue
            if max(perp(grid,M,a,j,'row'), perp(grid,M,b,j,'row')) >= ln:
                for i in range(a+1,b):
                    if g[i][j]==bg: g[i][j]=2
    for p,q in combinations(sorted(M),2):
        if p[0]==q[0] or p[1]==q[1]: continue
        dr,dc=abs(p[0]-q[0]),abs(p[1]-q[1])
        if dr<=dc: continue
        l,r=(p,q) if p[1]<q[1] else (q,p)
        cr,cc=r[0],l[1]
        pl=perp(grid,M,l[0],l[1],'row')   # nearest mark in l's row
        pr=perp(grid,M,r[0],r[1],'col')   # nearest mark in r's col
        thr=int(lc*dr)
        if not (pl>=thr and pr>=thr): continue
        for i in range(min(l[0],cr)+1, max(l[0],cr)+1):
            if g[i][cc]==bg: g[i][cc]=2
        for j in range(min(cc,r[1]), max(cc,r[1])):
            if g[cr][j]==bg: g[cr][j]=2
    return g
