def conseq_fill(g,bg=9):
    h,w=len(g),len(g[0])
    o=[r[:] for r in g]
    for i in range(h):
        js=[j for j in range(w) if g[i][j]!=bg]
        for a,b in zip(js,js[1:]):
            for j in range(a+1,b):
                if o[i][j]==bg: o[i][j]=2
    for j in range(w):
        ks=[i for i in range(h) if g[i][j]!=bg]
        for a,b in zip(ks,ks[1:]):
            for i in range(a+1,b):
                if o[i][j]==bg: o[i][j]=2
    return o
